    public static function key(string $source):string { return 'outgoing_invoice_'.substr(hash('sha256',$source),0,24); }
    public static function messages(string $locale):array
    {
        $english=explode('-',$locale,2)[0]==='en';$messages=[];
        foreach(self::ENGLISH as$source=>$translation)$messages[self::key($source)]=$english?$translation:$source;
        return $messages;
    }
    public static function text(string $source,array $messages):string
    {
        if(isset($messages[self::key($source)]))return $messages[self::key($source)];
        if(preg_match('/\A(.+) · Unterteilung ([0-9]{2})\z/uD',$source,$parts))return self::text($parts[1],$messages).' · '.self::text('Unterteilung',$messages).' '.$parts[2];
        if(preg_match('/\ABitte „([^“]+)“ ausfüllen bzw\. prüfen\.\z/uD',$source,$parts)){
            $labels=['buyer_reference'=>'Empfängerreferenz / Leitweg-ID','seller_contact'=>'Ansprechperson / Rechnungsstelle','note'=>'Zusatztext für diese Rechnung','vat_reason'=>'Bei 0 %: tatsächlicher Grund der Steuerbefreiung','contact_id'=>'Kontaktverknüpfung','payment_account'=>'Zahlungskonto','sphere'=>'Vereinsbereich','account'=>'Sachkonto (optional)','tax_rate'=>'Umsatzsteuer'];
            return str_replace('{field}',self::text($labels[$parts[1]]??$parts[1],$messages),self::text('Bitte „{field}“ ausfüllen bzw. prüfen.',$messages));
        }
        if(preg_match('/\ABitte (Empfängerreferenz \/ Leitweg-ID|E-Mail des Empfängers|Ansprechperson \/ Rechnungsstelle) ergänzen\.\z/uD',$source,$parts))return str_replace('{field}',self::text($parts[1],$messages),self::text('Bitte {field} ergänzen.',$messages));
        if(preg_match('/\AVereinsdaten vervollständigen: (name|street|postcode|city)\.\z/uD',$source,$parts))return str_replace('{field}',self::text(['name'=>'Vereinsname','street'=>'Straße und Hausnummer','postcode'=>'Postleitzahl','city'=>'Ort'][$parts[1]],$messages),self::text('Vereinsdaten vervollständigen: {field}.',$messages));
        return OutgoingMailMessages::text($source,$messages);
    }
}
